  "settings.modelProvider.help.inputModalities": "Đặt các loại nội dung mô hình có thể nhận:\n\n- **Text**: Nhận nội dung văn bản. Bắt buộc.\n- **Images**: Nhận nội dung hình ảnh.\n- **Video**: Nhận nội dung video.\n- **PDF**: Nhận trực tiếp tài liệu PDF.",
  "settings.modelProvider.help.outputModalities": "Loại nội dung của phản hồi mô hình. Hiện chỉ hỗ trợ văn bản.",
  "settings.modelProvider.help.capabilities": "- **Structured output**: Hỗ trợ ràng buộc JSON Schema cho các trường, kiểu và cấu trúc đầu ra.\n- **Native web search**: Hỗ trợ khả năng tìm kiếm web tích hợp sẵn của API mô hình.\n- **Mid-conversation system messages**: Hỗ trợ chèn chỉ dẫn hệ thống giữa cuộc trò chuyện.\n\nKhông bật các khả năng mà mô hình không hỗ trợ.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Đặt các mức suy luận có sẵn trong chat. **Phải sắp xếp từ mức suy luận thấp nhất đến cao nhất**.\nKhông cấu hình mức suy luận mà mô hình không hỗ trợ.",
  "settings.modelProvider.help.reasoningLevelMapping": "Dùng biểu thức CEL để ánh xạ mức suy luận hiện tại, `reasoningLevel`, sang các trường yêu cầu API của mô hình. Đối tượng JSON trả về từ biểu thức sẽ được hợp nhất vào body yêu cầu gửi đi.",
  "settings.modelProvider.help.advanced": "**MFJS tool schema**: Bật khả năng tương thích Moonshot Flavored JSON Schema, thường dùng cho API mô hình Kimi của Moonshot. Chỉ bật khi API mô hình yêu cầu định dạng này.",
  "settings.modelProvider.help.followRecommendedConfig": "Khớp với cấu hình đề xuất dựa trên Model ID, Base URL và định dạng API. ZAICODE liên tục cập nhật đề xuất và tự động đồng bộ cho bạn.\nKhi bạn tự đổi một thiết lập, thiết lập đó trở thành quản lý thủ công và ngừng theo cập nhật đề xuất; các thiết lập khác vẫn do cấu hình thông minh quản lý.",
